int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, target;
    cin >> n >> target;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());

    int left = 0, right = n - 1;
    bool found = false;

    while (left < right) {
        int sum = a[left] + a[right];
        if (sum == target) {
            found = true;
            break;
        } else if (sum < target) {
            left++;
        } else {
            right--;
        }
    }

    cout << (found ? "YES" : "NO") << "\n";

    return 0;
}

