#include <bits/stdc++.h>
using namespace std;

// Find first index where a[i] >= target
int lowerBound(vector<int>& a, int target) {
    int lo = 0, hi = a.size();  // hi is exclusive
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo;  // Returns a.size() if not found
}

// Find last index where a[i] <= target
int upperBound(vector<int>& a, int target) {
    int lo = 0, hi = a.size();
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] <= target) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo - 1;  // Last valid position
}

