// Trial division factorization
vector<pair<int, int>> factorize(int n) {
    vector<pair<int, int>> factors;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            int count = 0;
            while (n % i == 0) {
                n /= i;
                count++;
            }
            factors.push_back({i, count});
        }
    }
    if (n > 1) factors.push_back({n, 1});
    return factors;
}

// SPF sieve for fast factorization
const int MAXN = 1e6 + 5;
int spf[MAXN];

void sieveSPF() {
    for (int i = 1; i < MAXN; i++) spf[i] = i;
    for (int i = 2; i * i < MAXN; i++) {
        if (spf[i] == i) {
            for (int j = i * i; j < MAXN; j += i) {
                if (spf[j] == j) spf[j] = i;
            }
        }
    }
}

vector<pair<int, int>> factorizeFast(int n) {
    vector<pair<int, int>> factors;
    while (n > 1) {
        int p = spf[n];
        int count = 0;
        while (n % p == 0) {
            n /= p;
            count++;
        }
        factors.push_back({p, count});
    }
    return factors;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = 360;
    auto factors = factorize(n);
    cout << n << " = ";
    for (auto& [p, e] : factors) {
        cout << p << "^" << e << " ";
    }
    cout << "\n";

    // Using SPF
    sieveSPF();
    auto fast = factorizeFast(n);
    cout << "Fast factorization: ";
    for (auto& [p, e] : fast) {
        cout << p << "^" << e << " ";
    }
    cout << "\n";

    return 0;
}

