}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e6;

int spf[MAXN + 1];        // smallest prime factor
int phi[MAXN + 1];        // Euler's totient
int mobius[MAXN + 1];     // Mobius function
int numDiv[MAXN + 1];     // number of divisors
long long sumDiv[MAXN + 1]; // sum of divisors

void sieveApplications() {
    for (int i = 1; i <= MAXN; i++) {
        spf[i] = i;
        phi[i] = i;
        mobius[i] = 1;
        numDiv[i] = 1;
        sumDiv[i] = 1;
    }

    for (int i = 2; i <= MAXN; i++) {
        if (spf[i] == i) {  // i is prime
            for (int j = i; j <= MAXN; j += i) {
                if (spf[j] == j) spf[j] = i;

                // Totient
                phi[j] -= phi[j] / i;

                // Mobius
                int cnt = 0, x = j;
                while (x % i == 0) { x /= i; cnt++; }
                if (cnt > 1) mobius[j] = 0;
                else if (cnt == 1) mobius[j] *= -1;
            }
        }
    }

    // Number of divisors and sum of divisors
    for (int i = 1; i <= MAXN; i++) {
        for (int j = i; j <= MAXN; j += i) {
            numDiv[j]++;
            sumDiv[j] += i;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    sieveApplications();

    int n = 12;
    cout << "SPF of " << n << ": " << spf[n] << "\n";
    cout << "Phi(" << n << "): " << phi[n] << "\n";
    cout << "Mobius(" << n << "): " << mobius[n] << "\n";
    cout << "NumDiv(" << n << "): " << numDiv[n] << "\n";
    cout << "SumDiv(" << n << "): " << sumDiv[n] << "\n";

    return 0;
}

