        List<List<Integer>> nested = Arrays.asList(
            Arrays.asList(1, 2, 3),
            Arrays.asList(4, 5, 6),
            Arrays.asList(7, 8, 9)
        );
        List<Integer> flat = nested.stream().flatMap(List::stream).collect(Collectors.toList());
        System.out.println("Flattened: " + flat);

        List<Integer> duplicates = Arrays.asList(3, 1, 4, 1, 5, 9, 2, 6, 5);
        List<Integer> uniqueSorted = duplicates.stream()
            .distinct().sorted(Comparator.reverseOrder()).collect(Collectors.toList());
        System.out.println("Unique sorted desc: " + uniqueSorted);

        IntSummaryStatistics stats = duplicates.stream().mapToInt(Integer::intValue).summaryStatistics();
        System.out.println("Stats: " + stats);

        String joined = words.stream().filter(s -> s.startsWith("a")).collect(Collectors.joining(", "));
        System.out.println("Joined: " + joined);
    }
}

