int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    int src = 0;
    vector<int> dist(n, -1);   // -1 means unvisited
    vector<int> parent(n, -1);
    queue<int> q;

    dist[src] = 0;
    q.push(src);

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    // Print distances
    cout << "Distances from " << src << ":\n";
    for (int i = 0; i < n; i++) {
        cout << i << " -> " << dist[i] << "\n";
    }

    // Reconstruct path to node 3
    int target = 3;
    if (dist[target] != -1) {
        vector<int> path;
        for (int v = target; v != -1; v = parent[v]) {
            path.push_back(v);
        }
        reverse(path.begin(), path.end());
        cout << "Path to " << target << ": ";
        for (int v : path) cout << v << " ";
        cout << "\n";
    }

    return 0;
}

