vector<vector<int>> adj;
vector<int> vis;
vector<int> parent;

// Recursive DFS
void dfs(int u) {
    vis[u] = 1;  // gray
    cout << u << " ";

    for (int v : adj[u]) {
        if (!vis[v]) {
            parent[v] = u;
            dfs(v);
        }
    }
    vis[u] = 2;  // black
}

// Iterative DFS
void dfsIterative(int src) {
    stack<int> st;
    st.push(src);

    while (!st.empty()) {
        int u = st.top();
        st.pop();

        if (vis[u]) continue;
        vis[u] = 1;
        cout << u << " ";

        for (int v : adj[u]) {
            if (!vis[v]) {
                parent[v] = u;
                st.push(v);
            }
        }
    }
}

