#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<int> state;  // 0=unvisited, 1=visiting, 2=done
bool hasCycle = false;
vector<int> cycle;

bool dfsCycle(int u) {
    state[u] = 1;  // gray

    for (int v : adj[u]) {
        if (state[v] == 1) {
            // Back edge found — cycle exists!
            hasCycle = true;
            return true;
        }
        if (state[v] == 0) {
            if (dfsCycle(v)) return true;
        }
    }

    state[u] = 2;  // black
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    adj.resize(n);
    state.assign(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }

    for (int i = 0; i < n; i++) {
        if (state[i] == 0) {
            if (dfsCycle(i)) break;
        }
    }

    cout << (hasCycle ? "Cycle detected" : "No cycle") << "\n";

    return 0;
}

#include <bits/stdc++.h>
