int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> adj(n);
    vector<int> indeg(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        indeg[v]++;
    }

    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> topo;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        topo.push_back(u);

        for (int v : adj[u]) {
            indeg[v]--;
            if (indeg[v] == 0) q.push(v);
        }
    }

    if (topo.size() != n) {
        cout << "Graph contains cycle!\n";
    } else {
        cout << "Topological order: ";
        for (int x : topo) cout << x << " ";
        cout << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<int> state;
stack<int> topoStack;
bool hasCycle = false;

void dfsTopo(int u) {
    state[u] = 1;  // gray

    for (int v : adj[u]) {
        if (state[v] == 1) hasCycle = true;  // back edge
        else if (state[v] == 0) dfsTopo(v);
    }

    state[u] = 2;  // black
    topoStack.push(u);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    adj.resize(n);
    state.assign(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
    }

    for (int i = 0; i < n; i++) {
        if (state[i] == 0) dfsTopo(i);
    }

    if (hasCycle) {
        cout << "Cycle detected!\n";
    } else {
        cout << "Topological order: ";
        while (!topoStack.empty()) {
            cout << topoStack.top() << " ";
            topoStack.pop();
        }
        cout << "\n";
    }

    return 0;
}

