using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> adj(n);
    vector<tuple<int,int,int>> edges;

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        edges.push_back({u, v, w});
    }

    // Step 1: Add dummy node n, connect to all with weight 0
    // Run Bellman-Ford from dummy to get h[v] (potential)
    const long long INF = 1e18;
    vector<long long> h(n + 1, 0);

    // Bellman-Ford on extended graph
    for (int i = 0; i < n; i++) {
        for (auto& [u, v, w] : edges) {
            if (h[u] + w < h[v]) h[v] = h[u] + w;
        }
        // Also check dummy edges (h[n] + 0 < h[v])
        for (int v = 0; v < n; v++) {
            if (h[n] + 0 < h[v]) h[v] = h[n];
        }
    }

    // Step 2: Reweight edges: w'(u,v) = w(u,v) + h[u] - h[v]
    vector<vector<pair<int,int>>> adjReweighted(n);
    for (auto& [u, v, w] : edges) {
        int newW = w + h[u] - h[v];
        adjReweighted[u].push_back({v, newW});
    }

    // Step 3: Run Dijkstra from every node
    vector<vector<long long>> dist(n, vector<long long>(n, INF));

    for (int src = 0; src < n; src++) {
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
        dist[src][src] = 0;
        pq.push({0, src});

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (d > dist[src][u]) continue;

            for (auto& [v, w] : adjReweighted[u]) {
                if (dist[src][u] + w < dist[src][v]) {
                    dist[src][v] = dist[src][u] + w;
                    pq.push({dist[src][v], v});
                }
            }
        }
    }

    // Step 4: Convert back: d(u,v) = d'(u,v) - h[u] + h[v]
    cout << "All-pairs shortest paths:\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (dist[i][j] == INF) cout << "INF ";
            else cout << (dist[i][j] - h[i] + h[j]) << " ";
        }
        cout << "\n";
    }

    return 0;
}

