    int n, W;
    cin >> n >> W;

    vector<pair<int,int>> items;  // {weight, value}

    for (int i = 0; i < n; i++) {
        int w, v, c;
        cin >> w >> v >> c;  // c = max copies

        // Binary decomposition
        int k = 1;
        while (c > 0) {
            int take = min(k, c);
            items.push_back({w * take, v * take});
            c -= take;
            k *= 2;
        }
    }

    // Standard 0/1 knapsack on decomposed items
    vector<long long> dp(W + 1, 0);
    for (auto& [w, v] : items) {
        for (int cap = W; cap >= w; cap--) {
            dp[cap] = max(dp[cap], dp[cap - w] + v);
        }
    }

    cout << "Max value (bounded): " << dp[W] << "\n";

    return 0;
}

