int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s1, s2;
    cin >> s1 >> s2;
    int n = s1.size(), m = s2.size();

    vector<vector<int>> dp(n + 1, vector<int>(m + 1));

    // Base cases
    for (int i = 0; i <= n; i++) dp[i][0] = i;  // Delete all
    for (int j = 0; j <= m; j++) dp[0][j] = j;  // Insert all

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1];  // No operation needed
            } else {
                dp[i][j] = 1 + min({
                    dp[i][j-1],    // Insert s2[j-1]
                    dp[i-1][j],    // Delete s1[i-1]
                    dp[i-1][j-1]   // Replace s1[i-1] with s2[j-1]
                });
            }
        }
    }

    cout << "Edit distance: " << dp[n][m] << "\n";

    // Reconstruct operations
    vector<string> ops;
    int i = n, j = m;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && s1[i-1] == s2[j-1]) {
            ops.push_back("MATCH " + string(1, s1[i-1]));
            i--; j--;
        } else if (j > 0 && (i == 0 || dp[i][j] == dp[i][j-1] + 1)) {
            ops.push_back("INSERT " + string(1, s2[j-1]));
            j--;
        } else if (i > 0 && (j == 0 || dp[i][j] == dp[i-1][j] + 1)) {
            ops.push_back("DELETE " + string(1, s1[i-1]));
            i--;
        } else {
            ops.push_back("REPLACE " + string(1, s1[i-1]) + "->" + string(1, s2[j-1]));
            i--; j--;
        }
    }

    reverse(ops.begin(), ops.end());
    for (auto& op : ops) cout << op << "\n";

    return 0;
}

