    vector<int> p(n + 1);  // p[i-1] x p[i] = dimensions of matrix i
    for (int i = 0; i <= n; i++) cin >> p[i];

    // dp[i][j] = min cost to multiply matrices i to j (1-indexed)
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    vector<vector<int>> split(n + 1, vector<int>(n + 1, 0));

    for (int len = 2; len <= n; len++) {  // Chain length
        for (int i = 1; i + len - 1 <= n; i++) {
            int j = i + len - 1;
            dp[i][j] = LLONG_MAX;

            for (int k = i; k < j; k++) {
                long long cost = dp[i][k] + dp[k+1][j] + 1LL * p[i-1] * p[k] * p[j];
                if (cost < dp[i][j]) {
                    dp[i][j] = cost;
                    split[i][j] = k;
                }
            }
        }
    }

    cout << "Min multiplication cost: " << dp[1][n] << "\n";

    // Reconstruct parenthesization
    function<void(int,int)> printOrder = [&](int i, int j) {
        if (i == j) {
            cout << "A" << i;
            return;
        }
        cout << "(";
        printOrder(i, split[i][j]);
        printOrder(split[i][j] + 1, j);
        cout << ")";
    };

    cout << "Optimal order: ";
    printOrder(1, n);
    cout << "\n";

    return 0;
}

