    }

    cout << "Max coins: " << dp[0][n + 1] << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = s.size();

    // Precompute palindrome table
    vector<vector<bool>> isPal(n, vector<bool>(n, false));
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) {
            if (s[i] == s[j] && (j - i <= 2 || isPal[i+1][j-1])) {
                isPal[i][j] = true;
            }
        }
    }

    // dp[i] = min cuts for s[0..i]
    vector<int> dp(n, INT_MAX);
    for (int i = 0; i < n; i++) {
        if (isPal[0][i]) {
            dp[i] = 0;
            continue;
        }
        for (int j = 1; j <= i; j++) {
            if (isPal[j][i] && dp[j-1] != INT_MAX) {
                dp[i] = min(dp[i], dp[j-1] + 1);
            }
        }
    }

    cout << "Min palindrome partitions: " << dp[n-1] + 1 << "\n";

    // Reconstruct partitions
    vector<vector<string>> partitions;
    function<void(int, vector<string>&)> backtrack = [&](int start, vector<string>& curr) {
        if (start == n) {
            partitions.push_back(curr);
            return;
        }
        for (int end = start; end < n; end++) {
            if (isPal[start][end]) {
                curr.push_back(s.substr(start, end - start + 1));
                backtrack(end + 1, curr);
                curr.pop_back();
            }
        }
    };

    vector<string> curr;
    backtrack(0, curr);

    cout << "All palindrome partitions:\n";
    for (auto& part : partitions) {
        for (auto& str : part) cout << str << " ";
        cout << "\n";
    }

    return 0;
}

