int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> keys(n), freq(n);
    for (int i = 0; i < n; i++) cin >> keys[i];
    for (int i = 0; i < n; i++) cin >> freq[i];

    // Prefix sum of frequencies
    vector<int> pref(n + 1, 0);
    for (int i = 0; i < n; i++) pref[i+1] = pref[i] + freq[i];

    auto sumFreq = [&](int i, int j) { return pref[j+1] - pref[i]; };

    // dp[i][j] = min search cost for keys i to j
    vector<vector<int>> dp(n, vector<int>(n, 0));
    vector<vector<int>> root(n, vector<int>(n, 0));

    for (int i = 0; i < n; i++) {
        dp[i][i] = freq[i];
        root[i][i] = i;
    }

    for (int len = 2; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            dp[i][j] = INT_MAX;

            for (int k = i; k <= j; k++) {
                int leftCost = (k > i) ? dp[i][k-1] : 0;
                int rightCost = (k < j) ? dp[k+1][j] : 0;
                int cost = leftCost + rightCost + sumFreq(i, j);

                if (cost < dp[i][j]) {
                    dp[i][j] = cost;
                    root[i][j] = k;
                }
            }
        }
    }

    cout << "Min search cost: " << dp[0][n-1] << "\n";

    // Print root choices
    cout << "Root table:\n";
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i <= j) cout << root[i][j] << " ";
            else cout << "- ";
        }
        cout << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
int diameter = 0;

// Returns longest downward path from u
int dfsDiameter(int u, int parent) {
    int max1 = 0, max2 = 0;  // Two longest child paths

    for (int v : adj[u]) {
        if (v == parent) continue;
        int childLen = dfsDiameter(v, u) + 1;

        if (childLen > max1) {
            max2 = max1;
            max1 = childLen;
        } else if (childLen > max2) {
            max2 = childLen;
        }
    }

    diameter = max(diameter, max1 + max2);
    return max1;
}

// Alternative: Two BFS approach
pair<int,int> bfsFarthest(int src, int n) {
    vector<int> dist(n, -1);
    queue<int> q;
    q.push(src);
    dist[src] = 0;

    int farNode = src;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                q.push(v);
                if (dist[v] > dist[farNode]) farNode = v;
            }
        }
    }
    return {farNode, dist[farNode]};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    adj.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // Method 1: Tree DP
    dfsDiameter(0, -1);
    cout << "Diameter (Tree DP): " << diameter << "\n";

    // Method 2: Two BFS
    auto [far1, d1] = bfsFarthest(0, n);
    auto [far2, d2] = bfsFarthest(far1, n);
    cout << "Diameter (Two BFS): " << d2 << "\n";
    cout << "Path from " << far1 << " to " << far2 << "\n";

    return 0;
}

