struct TreeNode {
    int val;
    TreeNode *left, *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int maxPathSum = INT_MIN;

// Returns max downward path starting from this node
int maxGain(TreeNode* root) {
    if (!root) return 0;

    int leftGain = max(maxGain(root->left), 0);    // Ignore negative paths
    int rightGain = max(maxGain(root->right), 0);

    // Path passing through this node
    int pathThroughRoot = root->val + leftGain + rightGain;
    maxPathSum = max(maxPathSum, pathThroughRoot);

    // Return max downward path
    return root->val + max(leftGain, rightGain);
}

int main() {
    // Build tree: -10, 9, 20, null, null, 15, 7
    TreeNode* root = new TreeNode(-10);
    root->left = new TreeNode(9);
    root->right = new TreeNode(20);
    root->right->left = new TreeNode(15);
    root->right->right = new TreeNode(7);

    maxGain(root);
    cout << "Max path sum: " << maxPathSum << "\n";

    return 0;
}

