vector<bool> removed;
int n;

void dfsSize(int u, int p) {
    subtreeSize[u] = 1;
    for (int v : adj[u]) {
        if (v != p && !removed[v]) {
            dfsSize(v, u);
            subtreeSize[u] += subtreeSize[v];
        }
    }
}

int dfsCentroid(int u, int p, int total) {
    for (int v : adj[u]) {
        if (v != p && !removed[v] && subtreeSize[v] > total / 2) {
            return dfsCentroid(v, u, total);
        }
    }
    return u;
}

// Centroid Decomposition
void decompose(int entry) {
    dfsSize(entry, -1);
    int c = dfsCentroid(entry, -1, subtreeSize[entry]);

    cout << "Centroid: " << c << " (subtree size: " << subtreeSize[entry] << ")\n";
    removed[c] = true;

    for (int v : adj[c]) {
        if (!removed[v]) {
            decompose(v);
        }
    }
}

