#include <bits/stdc++.h>
using namespace std;

// Count numbers in [0, X] with digit sum divisible by K
vector<int> digits;
int K;
long long dp[20][2][100];  // pos, tight, sum_mod

long long solveDigitDP(int pos, bool tight, int sumMod) {
    if (pos == digits.size()) {
        return sumMod == 0 ? 1 : 0;
    }

    long long& res = dp[pos][tight][sumMod];
    if (res != -1 && !tight) return res;

    long long ans = 0;
    int limit = tight ? digits[pos] : 9;

    for (int d = 0; d <= limit; d++) {
        bool newTight = tight && (d == limit);
        int newSum = (sumMod + d) % K;
        ans += solveDigitDP(pos + 1, newTight, newSum);
    }

    if (!tight) res = ans;
    return ans;
}

long long countValid(long long x) {
    if (x < 0) return 0;
    digits.clear();
    while (x > 0) {
        digits.push_back(x % 10);
        x /= 10;
    }
    reverse(digits.begin(), digits.end());
    if (digits.empty()) digits.push_back(0);

    memset(dp, -1, sizeof(dp));
    return solveDigitDP(0, true, 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long L, R;
    cin >> L >> R >> K;

    long long ans = countValid(R) - countValid(L - 1);
    cout << "Count in [" << L << ", " << R << "] with digit sum % " << K << " == 0: " << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long dp[65][2][2];  // pos, tight, prevOne
vector<int> bits;

long long solve(int pos, bool tight, bool prevOne) {
    if (pos == bits.size()) return 1;

    long long& res = dp[pos][tight][prevOne];
    if (res != -1 && !tight) return res;

    long long ans = 0;
    int limit = tight ? bits[pos] : 1;

    for (int d = 0; d <= limit; d++) {
        if (prevOne && d == 1) continue;  // No consecutive 1s
        bool newTight = tight && (d == limit);
        ans += solve(pos + 1, newTight, d == 1);
    }

    if (!tight) res = ans;
    return ans;
}

long long countNoConsecutiveOnes(long long n) {
    bits.clear();
    while (n > 0) {
        bits.push_back(n & 1);
        n >>= 1;
    }
    reverse(bits.begin(), bits.end());
    if (bits.empty()) bits.push_back(0);

    memset(dp, -1, sizeof(dp));
    return solve(0, true, false);
}

