    cout << "Fibonacci check: F(" << N + 2 << ") = ";
    long long a = 0, b = 1;
    for (int i = 0; i <= N + 1; i++) {
        long long c = a + b;
        a = b;
        b = c;
    }
    cout << a << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
// dp[u][0] = u not matched to parent
// dp[u][1] = u matched to parent (so u can't match to any child)
int dp[100005][2];

void solve(int u, int parent) {
    dp[u][0] = 0;
    dp[u][1] = 0;

    for (int v : adj[u]) {
        if (v == parent) continue;
        solve(v, u);
    }

    // Case 1: u is matched to parent -> children must be unmatched to u
    dp[u][1] = 0;
    for (int v : adj[u]) {
        if (v == parent) continue;
        dp[u][1] += dp[v][0];  // v cannot be matched to u
    }

    // Case 2: u is free -> can match to at most one child
    dp[u][0] = dp[u][1];  // Start: don't match u to any child

    for (int v : adj[u]) {
        if (v == parent) continue;
        // Try matching u-v: gain 1 + v matched to u + other children free
        int gain = 1 + dp[v][1];
        for (int w : adj[u]) {
            if (w == parent || w == v) continue;
            gain += dp[w][0];
        }
        dp[u][0] = max(dp[u][0], gain);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    adj.resize(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    solve(0, -1);
    cout << "Maximum matching: " << max(dp[0][0], dp[0][1]) << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> computeLPS(const string& pat) {
    int m = pat.size();
    vector<int> lps(m, 0);
    int len = 0;  // Length of previous longest prefix suffix

    for (int i = 1; i < m; ) {
        if (pat[i] == pat[len]) {
            lps[i++] = ++len;
        } else if (len > 0) {
            len = lps[len - 1];  // Fall back
        } else {
            lps[i++] = 0;
        }
    }
    return lps;
}

void kmpSearch(const string& text, const string& pat) {
    int n = text.size(), m = pat.size();
    vector<int> lps = computeLPS(pat);

    int i = 0, j = 0;  // i for text, j for pattern
    while (i < n) {
        if (text[i] == pat[j]) {
            i++; j++;
        }

        if (j == m) {
            cout << "Pattern found at index " << i - j << "\n";
            j = lps[j - 1];  // Continue searching
        } else if (i < n && text[i] != pat[j]) {
            if (j > 0) j = lps[j - 1];
            else i++;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string text, pat;
    cin >> text >> pat;

    cout << "LPS array: ";
    vector<int> lps = computeLPS(pat);
    for (int x : lps) cout << x << " ";
    cout << "\n";

    kmpSearch(text, pat);

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> zFunction(const string& s) {
    int n = s.size();
    vector<int> z(n, 0);
    int L = 0, R = 0;  // [L,R] is the current Z-box

    for (int i = 1; i < n; i++) {
        if (i <= R) {
            z[i] = min(R - i + 1, z[i - L]);
        }

        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }

        if (i + z[i] - 1 > R) {
            L = i;
            R = i + z[i] - 1;
        }
    }
    return z;
}

void zSearch(const string& text, const string& pat) {
    string concat = pat + "$" + text;
    vector<int> z = zFunction(concat);

    int m = pat.size();
    for (int i = m + 1; i < concat.size(); i++) {
        if (z[i] == m) {
            cout << "Pattern found at index " << i - m - 1 << "\n";
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    vector<int> z = zFunction(s);
    cout << "Z-array: ";
    for (int x : z) cout << x << " ";
    cout << "\n";

    // Pattern matching example
    string text, pat;
    cin >> text >> pat;
    zSearch(text, pat);

    return 0;
}

