    int n = concat.size(), m = pat.size();
    int L = 0, R = 0;
    int count = 0;

    for (int i = 1; i < n; i++) {
        if (i <= R) z[i] = min(R - i + 1, z[i - L]);
        while (i + z[i] < n && concat[z[i]] == concat[i + z[i]]) z[i]++;
        if (i + z[i] - 1 > R) { L = i; R = i + z[i] - 1; }

