#include <bits/stdc++.h>
using namespace std;

int findPeriod(const string& s) {
    int n = s.size();
    vector<int> lps(n, 0);
    int len = 0;

    for (int i = 1; i < n; ) {
        if (s[i] == s[len]) lps[i++] = ++len;
        else if (len > 0) len = lps[len - 1];
        else lps[i++] = 0;
    }

    int candidate = n - lps[n - 1];
    if (n % candidate == 0) return candidate;
    return n;
}

