        cout << "String is periodic: ";
        for (int i = 0; i < p; i++) cout << s[i];
        cout << " repeated " << s.size() / p << " times\n";
    } else {
        cout << "String is not periodic\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct DoubleHash {
    static const int MOD1 = 1e9 + 7, MOD2 = 1e9 + 9;
    static const int BASE1 = 911, BASE2 = 357;
    vector<long long> pref1, pref2, pow1, pow2;

    DoubleHash(const string& s) {
        int n = s.size();
        pref1.resize(n + 1);
        pref2.resize(n + 1);
        pow1.resize(n + 1);
        pow2.resize(n + 1);

        pow1[0] = pow2[0] = 1;
        for (int i = 0; i < n; i++) {
            pow1[i+1] = (pow1[i] * BASE1) % MOD1;
            pow2[i+1] = (pow2[i] * BASE2) % MOD2;
            pref1[i+1] = (pref1[i] * BASE1 + s[i]) % MOD1;
            pref2[i+1] = (pref2[i] * BASE2 + s[i]) % MOD2;
        }
    }

    pair<long long,long long> getHash(int l, int r) {  // [l, r]
        long long h1 = (pref1[r+1] - pref1[l] * pow1[r-l+1] % MOD1 + MOD1) % MOD1;
        long long h2 = (pref2[r+1] - pref2[l] * pow2[r-l+1] % MOD2 + MOD2) % MOD2;
        return {h1, h2};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, pat;
    cin >> s >> pat;

    DoubleHash hs(s), hpat(pat);
    auto target = hpat.getHash(0, pat.size() - 1);

    vector<int> matches;
    for (int i = 0; i + pat.size() <= s.size(); i++) {
        if (hs.getHash(i, i + pat.size() - 1) == target) {
            matches.push_back(i);
        }
    }

    cout << "Matches at: ";
    for (int x : matches) cout << x << " ";
    cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> buildSuffixArray(const string& s) {
    string str = s + "$";
    int n = str.size();
    vector<int> sa(n), ranks(n), newRanks(n);

    // Initial ranking by first character
    for (int i = 0; i < n; i++) {
        sa[i] = i;
        ranks[i] = str[i];
    }

    for (int k = 1; k < n; k *= 2) {
        auto cmp = [&](int i, int j) {
            if (ranks[i] != ranks[j]) return ranks[i] < ranks[j];
            int ri = (i + k < n) ? ranks[i + k] : -1;
            int rj = (j + k < n) ? ranks[j + k] : -1;
            return ri < rj;
        };

        sort(sa.begin(), sa.end(), cmp);

        newRanks[sa[0]] = 0;
        for (int i = 1; i < n; i++) {
            newRanks[sa[i]] = newRanks[sa[i-1]] + (cmp(sa[i-1], sa[i]) ? 1 : 0);
        }
        ranks = newRanks;
        if (ranks[sa[n-1]] == n - 1) break;
    }

    return sa;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    vector<int> sa = buildSuffixArray(s);

    cout << "Suffix Array:\n";
    for (int i = 0; i < sa.size(); i++) {
        cout << i << ": " << sa[i] << " -> " << s.substr(sa[i]) << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> buildLCP(const string& s, const vector<int>& sa) {
    int n = sa.size();
    vector<int> rank(n), lcp(n, 0);

    for (int i = 0; i < n; i++) rank[sa[i]] = i;

    int k = 0;
    for (int i = 0; i < n - 1; i++) {
        if (rank[i] == 0) continue;  // SA[0] has no previous suffix
        int j = sa[rank[i] - 1];

        while (i + k < n && j + k < n && s[i + k] == s[j + k]) k++;
        lcp[rank[i]] = k;
        if (k > 0) k--;
    }

    return lcp;
}

