        while (i + k < n && j + k < n && s[i+k] == s[j+k]) k++;
        lcp[rank[i]] = k;
        if (k > maxLCP) { maxLCP = k; maxPos = sa[rank[i]]; }
        if (k > 0) k--;
    }

    cout << "Longest repeated substring length: " << maxLCP << "\n";
    if (maxLCP > 0) {
        cout << "Substring: " << s.substr(maxPos, maxLCP) << "\n";
    }

    return 0;
}

