    vector<int> sa(n + 1);
    iota(sa.begin(), sa.end(), 0);
    sort(sa.begin(), sa.end(), [&](int i, int j) {
        return s.substr(i) < s.substr(j);
    });

    // LCP
    vector<int> rank(n + 1), lcp(n + 1, 0);
    for (int i = 0; i <= n; i++) rank[sa[i]] = i;

    int k = 0;
    long long lcpSum = 0;
    for (int i = 0; i < n; i++) {
        if (rank[i] == 0) continue;
        int j = sa[rank[i] - 1];
        while (i + k < n && j + k < n && s[i+k] == s[j+k]) k++;
        lcp[rank[i]] = k;
        lcpSum += k;
        if (k > 0) k--;
    }

    long long total = 1LL * n * (n + 1) / 2;
    cout << "Total substrings: " << total << "\n";
    cout << "Distinct substrings: " << total - lcpSum << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct TrieNode {
    TrieNode* children[26];
    bool isEnd;
    int count;  // Number of words with this prefix

    TrieNode() {
        memset(children, 0, sizeof(children));
        isEnd = false;
        count = 0;
    }
};

class Trie {
    TrieNode* root;

public:
    Trie() { root = new TrieNode(); }

    void insert(const string& word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx]) {
                node->children[idx] = new TrieNode();
            }
            node = node->children[idx];
            node->count++;
        }
        node->isEnd = true;
    }

    bool search(const string& word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx]) return false;
            node = node->children[idx];
        }
        return node->isEnd;
    }

    bool startsWith(const string& prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!node->children[idx]) return false;
            node = node->children[idx];
        }
        return true;
    }

    int countPrefix(const string& prefix) {
        TrieNode* node = root;
        for (char c : prefix) {
            int idx = c - 'a';
            if (!node->children[idx]) return 0;
            node = node->children[idx];
        }
        return node->count;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Trie trie;
    vector<string> words = {"cat", "cars", "cart", "card", "dog"};

    for (auto& w : words) trie.insert(w);

    cout << "Search 'cat': " << trie.search("cat") << "\n";
    cout << "Search 'car': " << trie.search("car") << "\n";
    cout << "StartsWith 'car': " << trie.startsWith("car") << "\n";
    cout << "Count prefix 'car': " << trie.countPrefix("car") << "\n";
    cout << "Count prefix 'ca': " << trie.countPrefix("ca") << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct BinaryTrie {
    struct Node {
        Node* child[2];
        Node() { child[0] = child[1] = nullptr; }
    };

    Node* root;
    BinaryTrie() { root = new Node(); }

    void insert(int num) {
        Node* node = root;
        for (int i = 30; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (!node->child[bit]) node->child[bit] = new Node();
            node = node->child[bit];
        }
    }

    int maxXor(int num) {
        Node* node = root;
        int ans = 0;
        for (int i = 30; i >= 0; i--) {
            int bit = (num >> i) & 1;
            int want = 1 - bit;
            if (node->child[want]) {
                ans |= (1 << i);
                node = node->child[want];
            } else {
                node = node->child[bit];
            }
        }
        return ans;
    }
};

