    int pref = 0, maxSubarrayXor = 0;
    for (int x : a) {
        pref ^= x;
        maxSubarrayXor = max(maxSubarrayXor, trie.maxXor(pref));
        trie.insert(pref);
    }

    cout << "Maximum subarray XOR: " << maxSubarrayXor << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct SuffixAutomaton {
    struct State {
        int len, link;
        map<char, int> next;
        long long occ;  // Occurrence count (endpos size)
        State() : len(0), link(-1), occ(0) {}
    };

    vector<State> st;
    int last;

    SuffixAutomaton(int maxLen = 0) {
        st.reserve(2 * maxLen);
        st.push_back(State());  // State 0 = initial
        last = 0;
    }

    void extend(char c) {
        int cur = st.size();
        st.push_back(State());
        st[cur].len = st[last].len + 1;
        st[cur].occ = 1;  // New end position

        int p = last;
        while (p != -1 && !st[p].next.count(c)) {
            st[p].next[c] = cur;
            p = st[p].link;
        }

        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[c];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = st.size();
                st.push_back(st[q]);
                st[clone].len = st[p].len + 1;
                st[clone].occ = 0;  // Clone is not a real end position

                while (p != -1 && st[p].next[c] == q) {
                    st[p].next[c] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
    }

    void buildOccurrences() {
        // Sort states by length descending
        int maxLen = 0;
        for (auto& s : st) maxLen = max(maxLen, s.len);

        vector<vector<int>> buckets(maxLen + 1);
        for (int i = 0; i < st.size(); i++) {
            buckets[st[i].len].push_back(i);
        }

        for (int i = maxLen; i > 0; i--) {
            for (int u : buckets[i]) {
                if (st[u].link != -1) {
                    st[st[u].link].occ += st[u].occ;
                }
            }
        }
    }

    long long distinctSubstrings() {
        long long ans = 0;
        for (int i = 1; i < st.size(); i++) {
            ans += st[i].len - st[st[i].link].len;
        }
        return ans;
    }

    bool contains(const string& s) {
        int state = 0;
        for (char c : s) {
            if (!st[state].next.count(c)) return false;
            state = st[state].next[c];
        }
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    SuffixAutomaton sam(s.size());
    for (char c : s) sam.extend(c);
    sam.buildOccurrences();

    cout << "States: " << sam.st.size() << "\n";
    cout << "Distinct substrings: " << sam.distinctSubstrings() << "\n";

    // Check substring
    string q;
    cin >> q;
    cout << "Contains '" << q << "': " << sam.contains(q) << "\n";

    // Occurrence count
    int state = 0;
    for (char c : q) state = sam.st[state].next[c];
    cout << "Occurrences of '" << q << "': " << sam.st[state].occ << "\n";

    return 0;
}

#include <bits/stdc++.h>
