    cin >> a >> b;

    SAM sam(a.size());
    for (char c : a) sam.extend(c);

    int v = 0, l = 0, best = 0, bestPos = 0;
    for (int i = 0; i < b.size(); i++) {
        char c = b[i];
        if (sam.st[v].next.count(c)) {
            v = sam.st[v].next[c];
            l++;
        } else {
            while (v != -1 && !sam.st[v].next.count(c)) {
                v = sam.st[v].link;
            }
            if (v == -1) { v = 0; l = 0; }
            else { l = sam.st[v].len + 1; v = sam.st[v].next[c]; }
        }
        if (l > best) { best = l; bestPos = i - l + 1; }
    }

    cout << "Longest common substring length: " << best << "\n";
    if (best > 0) {
        cout << "Substring: " << b.substr(bestPos, best) << "\n";
    }

    return 0;
}

