// Determine winner of Nim
bool nimWinner(vector<int>& heaps) {
    int xorsum = 0;
    for (int h : heaps) xorsum ^= h;
    return xorsum != 0;  // true = first player wins
}

// Find a winning move
pair<int,int> findNimMove(vector<int>& heaps) {
    int xorsum = 0;
    for (int h : heaps) xorsum ^= h;

    if (xorsum == 0) return {-1, -1};  // No winning move

    for (int i = 0; i < heaps.size(); i++) {
        int target = heaps[i] ^ xorsum;
        if (target < heaps[i]) {
            return {i, heaps[i] - target};  // {heap_index, stones_to_remove}
        }
    }
    return {-1, -1};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> heaps(n);
    for (int i = 0; i < n; i++) cin >> heaps[i];

    int xorsum = 0;
    for (int h : heaps) xorsum ^= h;

    cout << "Nim-sum: " << xorsum << "\n";
    cout << (nimWinner(heaps) ? "First player wins!" : "Second player wins!") << "\n";

    auto move = findNimMove(heaps);
    if (move.first != -1) {
        cout << "Winning move: remove " << move.second 
             << " stones from heap " << move.first 
             << " (" << heaps[move.first] << " -> " 
             << heaps[move.first] - move.second << ")\n";
    }

    return 0;
}

