// Grundy numbers for common games

// 1. Single pile: take 1, 2, or 3 stones
int grundyTakeAway(int n) {
    // g(n) = mex{g(n-1), g(n-2), g(n-3)}
    // Pattern: 0,1,2,0,1,2,0,1,2... (period 3)
    return n % 3;
}

// 2. Wythoff's game: take from one pile or same amount from both
// Grundy is related to golden ratio — complex, use table for small n

// 3. Kayles: remove 1 or 2 adjacent pins from a row
// Splits into independent subgames

// General mex function
int mex(const vector<int>& s) {
    vector<bool> seen(s.size() + 1, false);
    for (int x : s) if (x < seen.size()) seen[x] = true;
    for (int i = 0; i < seen.size(); i++) if (!seen[i]) return i;
    return seen.size();
}

// Compute Grundy numbers for a subtraction game
vector<int> computeGrundy(int maxN, const vector<int>& moves) {
    vector<int> g(maxN + 1, 0);
    for (int i = 1; i <= maxN; i++) {
        vector<int> reachable;
        for (int m : moves) {
            if (i - m >= 0) reachable.push_back(g[i - m]);
        }
        g[i] = mex(reachable);
    }
    return g;
}

