    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Subtraction game: can remove 1, 3, or 4 stones
    vector<int> moves = {1, 3, 4};
    auto g = computeGrundy(20, moves);

    cout << "Grundy numbers (moves {1,3,4}):\n";
    for (int i = 0; i <= 20; i++) {
        cout << "g(" << i << ") = " << g[i] << "\n";
    }

    // Pattern detection
    cout << "\nPattern check (period 7 expected):\n";
    for (int i = 0; i < 14; i++) {
        cout << g[i] << " ";
    }
    cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj;
vector<int> grundy;

int computeGrundy(int u) {
    if (grundy[u] != -1) return grundy[u];

    vector<int> childGrundies;
    for (int v : adj[u]) {
        childGrundies.push_back(computeGrundy(v));
    }

    // mex
    vector<bool> seen(childGrundies.size() + 1, false);
    for (int g : childGrundies) {
        if (g < seen.size()) seen[g] = true;
    }

    grundy[u] = 0;
    while (grundy[u] < seen.size() && seen[grundy[u]]) grundy[u]++;
    return grundy[u];
}

