// Green Hackenbush on trees: value = XOR of (child_value + 1)
int hackenbushValue(int u, int parent) {
    int val = 0;
    for (int v : adj[u]) {
        if (v != parent) {
            val ^= (hackenbushValue(v, u) + 1);
        }
    }
    return val;
}

