int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, target;
    cin >> n >> target;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int n1 = n / 2, n2 = n - n1;

    // Generate all subset sums for first half
    vector<long long> left;
    for (int mask = 0; mask < (1 << n1); mask++) {
        long long sum = 0;
        for (int i = 0; i < n1; i++) {
            if (mask & (1 << i)) sum += a[i];
        }
        left.push_back(sum);
    }

    // Generate all subset sums for second half
    vector<long long> right;
    for (int mask = 0; mask < (1 << n2); mask++) {
        long long sum = 0;
        for (int i = 0; i < n2; i++) {
            if (mask & (1 << i)) sum += a[n1 + i];
        }
        right.push_back(sum);
    }

    sort(right.begin(), right.end());

    // Find subset sum closest to target
    long long bestDiff = LLONG_MAX, bestSum = 0;
    for (long long s1 : left) {
        long long need = target - s1;
        auto it = lower_bound(right.begin(), right.end(), need);

        if (it != right.end()) {
            long long total = s1 + *it;
            if (abs(total - target) < bestDiff) {
                bestDiff = abs(total - target);
                bestSum = total;
            }
        }
        if (it != right.begin()) {
            it--;
            long long total = s1 + *it;
            if (abs(total - target) < bestDiff) {
                bestDiff = abs(total - target);
                bestSum = total;
            }
        }
    }

    cout << "Closest sum to " << target << ": " << bestSum 
         << " (diff: " << bestDiff << ")\n";

    return 0;
}

