struct SlopeTrick {
    // Maintains f(x) = sum |x - a_i| + shift
    // Left side: max heap (negated for min-heap behavior)
    // Right side: min heap
    priority_queue<long long> L;  // max heap
    priority_queue<long long, vector<long long>, greater<>> R;  // min heap
    long long minValue = 0;
    long long addL = 0, addR = 0;  // Lazy shifts

    void addAbs(long long a) {
        // Add |x - a| to function
        if (!L.empty() && a < topL()) {
            minValue += topL() - a;
            pushR(topL());
            popL();
            pushL(a);
            pushL(a);
        } else if (!R.empty() && a > topR()) {
            minValue += a - topR();
            pushL(topR());
            popR();
            pushR(a);
            pushR(a);
        } else {
            pushL(a);
            pushR(a);
        }
    }

    long long getMin() { return minValue; }

    // Helpers with lazy shifts
    long long topL() { return L.top() + addL; }
    long long topR() { return R.top() + addR; }
    void pushL(long long x) { L.push(x - addL); }
    void pushR(long long x) { R.push(x - addR); }
    void popL() { L.pop(); }
    void popR() { R.pop(); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    SlopeTrick st;
    for (long long x : a) st.addAbs(x);

    cout << "Minimum sum of absolute deviations: " << st.getMin() << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

// Fast scanner for integers
class FastScanner {
private:
    static const int BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    int idx, size;

    inline char read() {
        if (idx >= size) {
            size = fread(buf, 1, BUFSIZE, stdin);
            idx = 0;
            if (size == 0) return EOF;
        }
        return buf[idx++];
    }

public:
    FastScanner() : idx(0), size(0) {}

    template<typename T>
    bool nextInt(T& out) {
        char c;
        T sign = 1;
        T val = 0;

        c = read();
        if (c == EOF) return false;

        while (c != '-' && (c < '0' || c > '9')) {
            c = read();
            if (c == EOF) return false;
        }

        if (c == '-') {
            sign = -1;
            c = read();
        }

        for (; c >= '0' && c <= '9'; c = read()) {
            val = val * 10 + (c - '0');
        }

        out = val * sign;
        return true;
    }
};

int main() {
    // Use FastScanner for massive input
    FastScanner fs;
    int n;
    fs.nextInt(n);

    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int x;
        fs.nextInt(x);
        sum += x;
    }

    cout << sum << "\n";

    return 0;
}

