    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (rand() % 2) adj[i].set(j);
        }
    }

    // Transitive closure using bitsets (Warshall-Floyd optimization)
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            if (adj[i][k]) adj[i] |= adj[k];
        }
    }

    // Count reachable pairs
    long long reachable = 0;
    for (int i = 0; i < n; i++) {
        reachable += adj[i].count();
    }

    cout << "Reachable pairs: " << reachable << "\n";

    // Knapsack with bitset
    int maxSum = 100000;
    bitset<100001> knapsack;
    knapsack[0] = 1;

    vector<int> weights = {2, 3, 5, 7, 11, 13};
    for (int w : weights) {
        knapsack |= (knapsack << w);
    }

    cout << "Achievable sums: ";
    for (int i = 0; i <= 30; i++) {
        if (knapsack[i]) cout << i << " ";
    }
    cout << "\n";

    return 0;
}

