struct Query {
    int l, r, idx, block;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int blockSize = max(1, (int)sqrt(n));

    vector<Query> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].l--; queries[i].r--;  // 0-indexed
        queries[i].idx = i;
        queries[i].block = queries[i].l / blockSize;
    }

    // Sort: by block, then R (alternating direction for optimization)
    sort(queries.begin(), queries.end(), [&](const Query& a, const Query& b) {
        if (a.block != b.block) return a.block < b.block;
        return (a.block % 2 == 0) ? a.r < b.r : a.r > b.r;
    });

    // Answer queries: count distinct elements
    vector<int> freq(*max_element(a.begin(), a.end()) + 1, 0);
    vector<int> ans(q);
    int curL = 0, curR = -1;
    int distinct = 0;

    auto add = [&](int pos) {
        freq[a[pos]]++;
        if (freq[a[pos]] == 1) distinct++;
    };

    auto remove = [&](int pos) {
        freq[a[pos]]--;
        if (freq[a[pos]] == 0) distinct--;
    };

    for (const auto& qu : queries) {
        while (curL > qu.l) add(--curL);
        while (curR < qu.r) add(++curR);
        while (curL < qu.l) remove(curL++);
        while (curR > qu.r) remove(curR--);

        ans[qu.idx] = distinct;
    }

    for (int x : ans) cout << x << "\n";

    return 0;
}

