#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int blockSize = sqrt(n) + 1;
    int numBlocks = (n + blockSize - 1) / blockSize;

    // Block sums
    vector<long long> blockSum(numBlocks, 0);
    for (int i = 0; i < n; i++) {
        blockSum[i / blockSize] += a[i];
    }

    while (q--) {
        int type, l, r;
        cin >> type >> l >> r;
        l--; r--;

        if (type == 1) {  // Range sum query
            long long sum = 0;
            int startBlock = l / blockSize;
            int endBlock = r / blockSize;

            if (startBlock == endBlock) {
                for (int i = l; i <= r; i++) sum += a[i];
            } else {
                // Left partial block
                for (int i = l; i < (startBlock + 1) * blockSize && i < n; i++) 
                    sum += a[i];
                // Middle full blocks
                for (int b = startBlock + 1; b < endBlock; b++) 
                    sum += blockSum[b];
                // Right partial block
                for (int i = endBlock * blockSize; i <= r; i++) 
                    sum += a[i];
            }
            cout << sum << "\n";
        } else {  // Point update
            int pos = l, val = r + 1;  // r is value in this case
            int b = pos / blockSize;
            blockSum[b] += val - a[pos];
            a[pos] = val;
        }
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

long long power(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = res * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q, k;
    cin >> n >> q >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    int blockSize = sqrt(n) + 1;
    int numBlocks = (n + blockSize - 1) / blockSize;

    // Precompute block sums of a[i]^k
    vector<long long> blockPow(numBlocks, 0);
    for (int i = 0; i < n; i++) {
        blockPow[i / blockSize] = (blockPow[i / blockSize] + power(a[i], k)) % MOD;
    }

    while (q--) {
        int l, r;
        cin >> l >> r;
        l--; r--;

        long long ans = 0;
        int startBlock = l / blockSize;
        int endBlock = r / blockSize;

        if (startBlock == endBlock) {
            for (int i = l; i <= r; i++) 
                ans = (ans + power(a[i], k)) % MOD;
        } else {
            for (int i = l; i < (startBlock + 1) * blockSize && i < n; i++) 
                ans = (ans + power(a[i], k)) % MOD;
            for (int b = startBlock + 1; b < endBlock; b++) 
                ans = (ans + blockPow[b]) % MOD;
            for (int i = endBlock * blockSize; i <= r; i++) 
                ans = (ans + power(a[i], k)) % MOD;
        }

        cout << ans << "\n";
    }

    return 0;
}
